import json, re, sys

path = sys.argv[1]
kws = sys.argv[2:]
d = json.load(open(path, encoding="utf-8"))
r = d["results"][0]
print("effective_time", r.get("effective_time"), r.get("openfda", {}).get("brand_name"), r.get("openfda", {}).get("manufacturer_name"))
for k, v in r.items():
    if not isinstance(v, list):
        continue
    for txt in v:
        if not isinstance(txt, str):
            continue
        for kw in kws:
            for m in re.finditer(kw, txt, flags=re.I):
                s = max(0, m.start() - 250)
                e = min(len(txt), m.end() + 350)
                print(f"[{k}] {kw}: ...{txt[s:e]}...")
                print("--")

