for k, v in r.items():
    if not isinstance(v, list):
        continue
    for txt in v:
        if not isinstance(txt, str):
            continue
        for kw in kws:
            for m in re.finditer(kw, txt, flags=re.I):
                s = max(0, m.start() - 250)
                e = min(len(txt), m.end() + 350)
                print(f"[{k}] {kw}: ...{txt[s:e]}...")
